def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def fact(num):
    res = 1
    for i in range(1, num + 1):
        res = res * i
    return res

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def search(lst, target):
    for i in range(len(lst)):
        if lst[i] == target:
            return i
    return -1

def bin_search(arr, x):
    l = 0
    r = len(arr) - 1
    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            l = mid + 1
        else:
            r = mid - 1
    return -1

