from typing import List

def add_matrices(matrix_a: List[List[float]], matrix_b: List[List[float]]) -> List[List[float]]:
    """Element-wise addition of two 2D matrices."""
    return [
        [val_a + val_b for val_a, val_b in zip(row_a, row_b)]
        for row_a, row_b in zip(matrix_a, matrix_b)
    ]

import math

def is_prime_number(number: int) -> bool:
    """Determine if a positive integer is prime."""
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    for i in range(5, int(math.isqrt(number)) + 1, 6):
        if number % i == 0 or number % (i + 2) == 0:
            return False
    return True

