from typing import List

def quicksort(elements: List[int]) -> List[int]:
    """Sort a list of integers using the quicksort algorithm."""
    if len(elements) <= 1:
        return elements
    pivot = elements[len(elements) // 2]
    left = [x for x in elements if x < pivot]
    middle = [x for x in elements if x == pivot]
    right = [x for x in elements if x > pivot]
    return quicksort(left) + middle + quicksort(right)

from typing import Any, Optional
from collections import deque

class Queue:
    """FIFO Queue implementation backed by collections.deque."""
    def __init__(self) -> None:
        self._items: deque[Any] = deque()
    def enqueue(self, item: Any) -> None:
        self._items.append(item)
    def dequeue(self) -> Optional[Any]:
        return self._items.popleft() if self._items else None

from typing import Generic, TypeVar, Optional
T = TypeVar('T')
class Stack(Generic[T]):
    def __init__(self) -> None:
        self._container: list[T] = []
    def push(self, element: T) -> None:
        self._container.append(element)
    def pop(self) -> Optional[T]:
        return self._container.pop() if self._container else None

