import math
from typing import Union

def calculate_circle_area(radius: Union[int, float]) -> float:
    """Calculate and return the area of a circle given its radius."""
    if radius < 0:
        raise ValueError('Radius cannot be negative')
    return math.pi * (radius ** 2)

def celsius_to_fahrenheit(celsius: float) -> float:
    """Convert temperature from Celsius to Fahrenheit scale."""
    return (celsius * 9.0 / 5.0) + 32.0

def find_maximum_of_three(a: float, b: float, c: float) -> float:
    """Return the maximum among three numbers using max built-in."""
    return max(a, b, c)

def count_vowels(input_string: str) -> int:
    """Count the total number of vowels present in the given string."""
    vowels = set('aeiouAEIOU')
    return sum(1 for char in input_string if char in vowels)

from typing import Union

def perform_arithmetic_operation(operand_a: float, operand_b: float, operator: str) -> float:
    """Execute basic arithmetic operation based on provided operator."""
    operations = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else float('nan'),
    }
    if operator not in operations:
        raise ValueError(f'Unsupported operator: {operator}')
    return operations[operator](operand_a, operand_b)

