from typing import Any, Sequence, Optional

def linear_search(sequence: Sequence[Any], target_item: Any) -> Optional[int]:
    """Search for target item in sequence and return its index if found."""
    for index, current_element in enumerate(sequence):
        if current_element == target_item:
            return index
    return None

